const directionAndRewards="<style>#game:not([hidden]) .climber .hiker{transform:none!important}#game:not([hidden]) .climber[data-facing=back] .hiker{aspect-ratio:1!important;width:200%!important;margin-left:-50%!important}#game:not([hidden]) .climber[data-facing=left] .hiker{transform:scaleX(-1)!important}#game:not([hidden]) .moving[data-facing=left] .hiker{animation:leftwardStride .4s ease-in-out infinite alternate!important}@keyframes leftwardStride{from{transform:scaleX(-1) translateY(0)}to{transform:scaleX(-1) translateY(-3px)}}</style><script>\nfunction routeDirection(points,t,aspect){const n=points.length-1,i=Math.min(n-1,Math.floor(Math.max(0,Math.min(1,t))*n));const dx=(points[i+1][0]-points[i][0])*aspect,dy=points[i+1][1]-points[i][1];return Math.abs(dy)>Math.abs(dx)*.85?(dy<0?'back':'front'):dx<0?'left':'right'}\nconst renderWithDirection=render;\nrender=function(){renderWithDirection();if(!state)return;const frame=document.querySelector('#game .frame'),points=questTrails[locationQuest-1],aspect=frame.clientWidth/Math.max(1,frame.clientHeight);for(const e of document.querySelectorAll('#climbers .climber')){const p=state.players.find(p=>p.id===e.dataset.id);if(!p)continue;const pq=questOf(p),t=pq<locationQuest?0:pq>locationQuest?1:Math.min(1,(Number(p.altitude)%1000)/900),direction=routeDirection(points,t,aspect),hiker=e.querySelector('.hiker');e.dataset.facing=direction;e.classList.remove('mountain-climbing');if(direction==='back'){const index=Object.keys(characterOutfits).indexOf(p.animal);hiker.style.backgroundImage='url(\"/characters/rear-atlas.png?v=1\")';hiker.style.setProperty('background-size','400% 300%','important');hiker.style.setProperty('background-position',((index%4)*100/3)+'% '+(Math.floor(index/4)*50)+'%','important')}else{hiker.style.removeProperty('background-size');hiker.style.removeProperty('background-position')}}};\n</script>";
