const serpantinRoadCamera="<style id=\"serpantin-road-camera-v2\">\n#game:not([hidden]) .frame{background-image:none!important;background-color:#294c44!important;overflow:hidden!important}\n#game:not([hidden]) #serpantin-photo-track{position:absolute;inset:-2%;z-index:1;pointer-events:none;background-image:url('/locations/serpantin-go-approved.png');background-repeat:no-repeat;background-size:100% 100%;background-position:center;will-change:transform;transition:transform 1.05s cubic-bezier(.2,.75,.25,1)}\n#game:not([hidden]) #climbers{z-index:55!important}\n#game:not([hidden]) #climbers .climber{z-index:56!important;transition:left 1s ease,bottom 1s ease,transform 1s ease!important;transform-origin:center bottom!important}\n@media(prefers-reduced-motion:reduce){#game:not([hidden]) #serpantin-photo-track,#game:not([hidden]) #climbers .climber{transition:none!important}}\n</style><script id=\"serpantin-road-camera-engine\">\n(function(){\nif(typeof render!=='function')return;\nconst prev=render;\nrender=function(){const result=prev.apply(this,arguments);try{\nconst frame=document.querySelector('#game:not([hidden]) .frame');\nif(!frame||!state||!Array.isArray(state.players))return result;\nlet bg=frame.querySelector('#serpantin-photo-track');if(!bg){bg=document.createElement('div');bg.id='serpantin-photo-track';frame.insertBefore(bg,frame.firstChild)}\nconst players=state.players,elems=[...frame.querySelectorAll('#climbers .climber')],fw=frame.clientWidth,fh=frame.clientHeight;if(!fw||!fh)return result;\nconst distances=players.map(p=>Math.max(0,Number(p.altitude)||0));\nconst min=distances.length?Math.min(...distances):0,max=distances.length?Math.max(...distances):0,span=Math.max(1000,max-min+400),lead=max/12000;\nconst turn=(max%3000)/3000;\nconst zoom=1.05+Math.min(.22,lead*.2);\nconst dx=Math.sin(turn*Math.PI*2)*Math.min(7,4+lead*4),dy=Math.min(7,lead*7);\nbg.style.transform='scale('+zoom.toFixed(3)+') translate('+dx.toFixed(2)+'%,'+dy.toFixed(2)+'%)';\nfor(const el of elems){const p=players.find(p=>String(p.id)===String(el.dataset.id));if(!p)continue;\nconst idx=players.indexOf(p),d=Math.max(0,Number(p.altitude)||0),relative=Math.max(0,Math.min(1,.5+(d-(min+max)/2)/span));\n/* Photo road: lower winding roadway, never the sky or mountain cliffs. */\nconst x=39+relative*18+(idx%4-1.5)*2.6;\nconst y=81-relative*12+(idx%3-1)*1.4;\nel.style.setProperty('left',x.toFixed(2)+'%','important');\nel.style.setProperty('bottom',(100-y).toFixed(2)+'%','important');\nel.style.setProperty('--route-scale',String(Math.max(.75,Math.min(1.12,fw/440))));\nel.style.setProperty('opacity','1','important');\nel.style.setProperty('visibility','visible','important');\nel.style.setProperty('display','block','important');\n}\n}catch(e){console.warn('Serpantin photo camera',e)}return result};\n})();\n</script>";
const serpantinLongRoute="<style id=\"serpantin-long-route-v3\">\n#game:not([hidden]) .frame{overflow:hidden!important;background:#344c40!important}\n#game:not([hidden]) #serpantin-photo-track{display:none!important}\n#game:not([hidden]) #serpantin-long-world{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:1;isolation:isolate}\n#game:not([hidden]) #serpantin-long-world .route-panel{position:absolute;left:-4%;width:108%;height:104%;background-image:url('/locations/serpantin-go-approved.png');background-size:cover;background-repeat:no-repeat;background-position:center;will-change:transform;transition:transform 1.15s ease}\n#game:not([hidden]) #serpantin-long-world .route-panel::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,transparent 72%,rgba(38,60,39,.12));pointer-events:none}\n#game:not([hidden]) #climbers{z-index:55!important}\n#game:not([hidden]) #climbers .climber{z-index:56!important;transition:left 1.05s ease,bottom 1.05s ease!important}\n@media(prefers-reduced-motion:reduce){#game:not([hidden]) #serpantin-long-world .route-panel{transition:none!important}}\n</style><script id=\"serpantin-long-route-engine\">\n(function(){\nif(typeof render!=='function')return;\nconst old=render;\nrender=function(){const result=old.apply(this,arguments);try{\nconst frame=document.querySelector('#game:not([hidden]) .frame');\nif(!frame||!state||!Array.isArray(state.players))return result;\nlet world=frame.querySelector('#serpantin-long-world');\nif(!world){world=document.createElement('div');world.id='serpantin-long-world';frame.insertBefore(world,frame.firstChild);for(let i=0;i<3;i++){const panel=document.createElement('div');panel.className='route-panel';panel.style.top=(i-1)*100+'%';world.appendChild(panel)}}\nconst players=state.players,meters=players.map(p=>Math.max(0,Number(p.altitude)||0)),lo=meters.length?Math.min(...meters):0,hi=meters.length?Math.max(...meters):0;\nconst center=(lo+hi)/2,step=1000,section=Math.floor(center/step),fraction=(center%step)/step;\nconst panels=[...world.children];for(let i=0;i<3;i++){const n=section+i-1;const p=panels[i];const offset=(i-1-fraction)*100;p.style.transform='translate3d(0,'+(-fraction*0).toFixed(2)+'%,0)';p.style.top=offset.toFixed(3)+'%';p.style.backgroundPosition=(40+(Math.abs(n)%5)*5)+'% '+(40+(Math.abs(n)%3)*8)+'%';p.style.filter='saturate('+(1.02+(Math.abs(n)%4)*.035)+') brightness('+(1+(Math.abs(n)%3)*.025)+')';}\nconst width=frame.clientWidth,height=frame.clientHeight;if(!width||!height)return result;\nconst range=Math.max(1200,hi-lo+500);\nfor(const el of frame.querySelectorAll('#climbers .climber')){const p=players.find(p=>String(p.id)===String(el.dataset.id));if(!p)continue;\nconst index=players.indexOf(p),m=Math.max(0,Number(p.altitude)||0),u=Math.max(0,Math.min(1,.5+(m-center)/range));\n/* Walkable road corridor of the approved autumn photo, from near foreground toward the distant bend. */\nconst y=85-u*18,x=38+u*24+(index%4-1.5)*2.2;\nel.style.setProperty('left',x.toFixed(2)+'%','important');el.style.setProperty('bottom',(100-y).toFixed(2)+'%','important');\nel.style.setProperty('--route-scale',String(Math.max(.72,Math.min(1.06,width/440))));\nel.style.setProperty('visibility','visible','important');el.style.setProperty('opacity','1','important');\n}\n}catch(e){console.warn('Long route camera',e)}return result};\n})();\n</script>";
